?>
<div class="d-flex align-items-start justify-content-between gap-3 mb-3"><div><h1 class="h4 mb-1"><?= Html::encode($this->title) ?></h1><p class="text-body-secondary mb-0">จัดการแบบประเมินแยกตามวิชาชีพและเก็บประวัติทุก revision</p></div><?= Html::a('สร้าง Template',['form'],['class'=>'btn btn-primary']) ?></div>
<section class="card bg-body border shadow-sm overflow-hidden"><?php if(!$models): ?><div class="text-center p-5"><h2 class="h5">ยังไม่มี Template</h2><p class="text-body-secondary">สร้างแบบประเมินแรกตามกลุ่มวิชาชีพ</p><?= Html::a('สร้าง Template',['form'],['class'=>'btn btn-primary']) ?></div><?php else: ?><div class="d-none d-lg-block"><table class="table table-hover align-middle mb-0"><thead class="table-group-divider"><tr><th>ชื่อ Template</th><th>วิชาชีพ</th><th>Revision</th><th>จำนวนข้อ</th><th>สถานะ</th><th class="text-end">จัดการ</th></tr></thead><tbody><?php foreach($models as $m): ?><tr><td class="fw-semibold"><?= Html::encode($m->name) ?></td><td><?= Html::encode($m->positionGroup->title??'—') ?></td><td><?= $m->revision_no ?></td><td><?= count($m->items) ?></td><td><span class="badge bg-<?= $badge($m->status) ?>-subtle text-<?= $badge($m->status) ?>-emphasis"><?= Html::encode($m->statusLabel) ?></span></td><td class="text-end"><?= Html::a('ดูรายละเอียด',['view','id'=>$m->id],['class'=>'btn btn-sm btn-outline-primary']) ?></td></tr><?php endforeach ?></tbody></table></div><ul class="list-group list-group-flush d-lg-none"><?php foreach($models as $m): ?><li class="list-group-item p-3"><div class="d-flex justify-content-between"><strong><?= Html::encode($m->name) ?></strong><span class="badge bg-<?= $badge($m->status) ?>-subtle text-<?= $badge($m->status) ?>-emphasis"><?= Html::encode($m->statusLabel) ?></span></div><div class="text-body-secondary small mt-1"><?= Html::encode($m->positionGroup->title??'—') ?> · rev. <?= $m->revision_no ?> · <?= count($m->items) ?> ข้อ</div><div class="d-grid mt-3"><?= Html::a('ดูรายละเอียด',['view','id'=>$m->id],['class'=>'btn btn-outline-primary']) ?></div></li><?php endforeach ?></ul><footer class="card-footer bg-body"><?= DataSummaryWidget::widget(['dataProvider'=>$dataProvider]) ?></footer><?php endif ?></section>
